def expected_has_pair_sum(xs, target):
    n = len(xs)
    for i in range(6):
        if i >= n:
            break
        for j in range(6):
            if j >= n:
                break
            if i != j:
                if xs[i] + xs[j] == target:
                    return True
    return False

def post(xs, target, result):
    expected = expected_has_pair_sum(xs, target)
    if expected:
        if result == True:
            return True
        return False
    else:
        if result == False:
            return True
        return False
